<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Employee accounts | Sun Son Solar</title><link rel="stylesheet" href="<?= base_url('style1.css') ?>"></head><body class="portal-body"><header class="portal-header"><a href="<?= site_url('staff') ?>">← Operations</a><strong>Employee account management</strong><a href="<?= site_url('logout') ?>">Log out</a></header><main class="portal-main"><h1>Employees</h1><?php if($msg=session()->getFlashdata('message')): ?><p class="notice"><?= esc($msg) ?></p><?php endif ?><?php if($errs=session()->getFlashdata('form_errors')): ?><p class="notice notice--error"><?= esc(implode(' ',$errs)) ?></p><?php endif ?><div class="portal-grid"><section class="portal-card"><h2>Add employee</h2><p>Set a temporary password and share it securely with the employee. Passwords are stored as hashes.</p><form method="post" action="<?= site_url('staff/users/create') ?>"><?= csrf_field() ?><div class="signup-grid"><?php foreach(['first_name'=>'First name','middle_name'=>'Middle name','last_name'=>'Last name','birthdate'=>'Birthdate','gender'=>'Gender','email'=>'Email','phone_number'=>'Phone','address'=>'Address','username'=>'Username','password'=>'Temporary password (12+ characters)'] as $key=>$label): ?><label><?= esc($label) ?><?php if($key==='gender'): ?><select name="gender"><option>Female</option><option>Male</option><option>Other</option></select><?php elseif($key==='address'): ?><textarea name="address" required></textarea><?php else: ?><input name="<?= esc($key) ?>" <?= $key==='birthdate'?'type="date"':($key==='email'?'type="email"':($key==='password'?'type="password"':'text')) ?> <?= $key==='middle_name'?'':'required' ?>><?php endif ?></label><?php endforeach ?><label>Department<select name="department_id" required><?php foreach($departments as $d): ?><option value="<?= (int)$d['department_id'] ?>"><?= esc($d['department_name']) ?></option><?php endforeach ?></select></label><label>Role<select name="role"><option value="employee">Employee</option><option value="technician">Technician</option><option value="dispatcher">Dispatcher</option><option value="hr">HR</option><option value="admin">Administrator</option></select></label></div><button class="auth-submit">Create employee</button></form></section><section class="portal-card"><h2>Active and inactive users</h2><?php foreach($employees as $employee): ?><article class="list-row"><strong><?= esc($employee['first_name'].' '.$employee['last_name']) ?></strong><p><?= esc($employee['role'].' · '.$employee['department_name'].' · '.$employee['username']) ?> · <?= esc($employee['email']) ?></p><details><summary>Edit employee</summary><form method="post" action="<?= site_url('staff/users/'.(int)$employee['employee_id']) ?>"><?= csrf_field() ?><label>First name<input name="first_name" value="<?= esc($employee['first_name']) ?>" required></label><label>Middle name<input name="middle_name" value="<?= esc($employee['middle_name']??'') ?>"></label><label>Last name<input name="last_name" value="<?= esc($employee['last_name']) ?>" required></label><label>Email<input type="email" name="email" value="<?= esc($employee['email']) ?>" required></label><label>Phone<input name="phone_number" value="<?= esc($employee['phone_number']) ?>" required></label><label>Address<textarea name="address" required><?= esc($employee['address']) ?></textarea></label><label>Department<select name="department_id"><?php foreach($departments as $d): ?><option value="<?= (int)$d['department_id'] ?>" <?= (int)$d['department_id']===(int)$employee['department_id']?'selected':'' ?>><?= esc($d['department_name']) ?></option><?php endforeach ?></select></label><label>Role<select name="role"><?php foreach(['employee','technician','dispatcher','hr','admin'] as $r): ?><option <?= $employee['role']===$r?'selected':'' ?>><?= esc($r) ?></option><?php endforeach ?></select></label><button class="small-button">Save changes</button></form></details><?php if($employee['is_active'] && (int)$employee['employee_id']!==(int)session('user_id')): ?><form method="post" action="<?= site_url('staff/users/'.(int)$employee['employee_id'].'/deactivate') ?>"><?= csrf_field() ?><button class="small-button">Deactivate account</button></form><?php endif ?></article><?php endforeach ?></section></div></main></body></html>
